import{_ as e,o,c as d,a3 as r}from"./chunks/framework.CpLciM8b.js";const l=JSON.parse('{"title":"API reference","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"reference/api.md","filePath":"reference/api.md","lastUpdated":null}'),a={name:"reference/api.md"};function n(s,t,c,i,h,p){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="api-reference" tabindex="-1">API reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API reference&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Generated file</p><p>This page is generated from the zod contracts and the router definitions at build time. Edit <code>packages/contracts/src/rest.ts</code> or the schemas themselves, not this page.</p></div><p>Flakemetry exposes two surfaces: a <strong>REST API</strong> for ingestion and CI integrations, authenticated with a per-project ingest token, and a <strong>tRPC API</strong> for dashboard queries.</p><h2 id="rest" tabindex="-1">REST <a class="header-anchor" href="#rest" aria-label="Permalink to &quot;REST&quot;">​</a></h2><p>All request and response bodies are JSON. Write endpoints validate against the schemas below and reject anything that does not match, so a malformed upload fails fast rather than corrupting history.</p><h3 id="get-health" tabindex="-1"><code>GET /health</code> <a class="header-anchor" href="#get-health" aria-label="Permalink to &quot;`GET /health`&quot;">​</a></h3><p>Liveness probe. Used by containers and load balancers.</p><p><strong>Auth:</strong> none</p><p><strong>Returns:</strong> <code>{ status: &quot;ok&quot;, service: &quot;api&quot; }</code></p><h3 id="post-v1-ingest" tabindex="-1"><code>POST /v1/ingest</code> <a class="header-anchor" href="#post-v1-ingest" aria-label="Permalink to &quot;`POST /v1/ingest`&quot;">​</a></h3><p>Ingest one test run. Validated and enqueued, then acknowledged immediately — this never blocks CI.</p><p><strong>Auth:</strong> project token with the <code>ingest</code> scope (<code>Authorization: Bearer …</code>)</p><p><strong>Returns:</strong> <code>202</code> with <code>{ receiptId, acceptedExecutions }</code></p><p><strong>IngestRunBatch</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>contractVersion</code></td><td>string</td><td>yes</td><td></td></tr><tr><td><code>idempotencyKey</code></td><td>string</td><td>yes</td><td></td></tr><tr><td><code>resource</code></td><td>object</td><td>yes</td><td></td></tr><tr><td><code>run</code></td><td>object</td><td>yes</td><td></td></tr><tr><td><code>executions</code></td><td>object[]</td><td>yes</td><td></td></tr></tbody></table><h3 id="post-v1-ingest-junit" tabindex="-1"><code>POST /v1/ingest/junit</code> <a class="header-anchor" href="#post-v1-ingest-junit" aria-label="Permalink to &quot;`POST /v1/ingest/junit`&quot;">​</a></h3><p>Ingest a JUnit XML report directly, for CI that cannot run the CLI. Parsed server-side into the same run batch the CLI would have sent.</p><p><strong>Auth:</strong> project token with the <code>ingest</code> scope (<code>Authorization: Bearer …</code>)</p><p><strong>Returns:</strong> <code>202</code> with <code>{ receiptId, acceptedExecutions }</code></p><p><strong>JunitIngestRequest</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>idempotencyKey</code></td><td>string</td><td>yes</td><td></td></tr><tr><td><code>resource</code></td><td>object</td><td>yes</td><td></td></tr><tr><td><code>xml</code></td><td>string</td><td>yes</td><td></td></tr></tbody></table><h3 id="post-v1-ingest-plugin-name" tabindex="-1"><code>POST /v1/ingest/plugin/:name</code> <a class="header-anchor" href="#post-v1-ingest-plugin-name" aria-label="Permalink to &quot;`POST /v1/ingest/plugin/:name`&quot;">​</a></h3><p>Ingest a report in a format an ingestion plugin understands. The named plugin parses <code>content</code> on the server into the same run batch as every other route; <code>404</code> lists the plugins that are loaded.</p><p><strong>Auth:</strong> project token with the <code>ingest</code> scope (<code>Authorization: Bearer …</code>)</p><p><strong>Returns:</strong> <code>202</code> with <code>{ receiptId, acceptedExecutions }</code></p><p><strong>PluginIngestRequest</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>idempotencyKey</code></td><td>string</td><td>yes</td><td></td></tr><tr><td><code>resource</code></td><td>object</td><td>yes</td><td></td></tr><tr><td><code>content</code></td><td>string</td><td>yes</td><td></td></tr></tbody></table><h3 id="post-v1-traces" tabindex="-1"><code>POST /v1/traces</code> <a class="header-anchor" href="#post-v1-traces" aria-label="Permalink to &quot;`POST /v1/traces`&quot;">​</a></h3><p>OTLP-HTTP trace ingestion for reporters that emit spans directly.</p><p><strong>Auth:</strong> project token with the <code>ingest</code> scope (<code>Authorization: Bearer …</code>)</p><p><strong>Returns:</strong> <code>202</code> with <code>{ receiptId, acceptedExecutions }</code></p><p><strong>OtlpTraceRequest</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>resourceSpans</code></td><td>object[]</td><td>no</td><td></td></tr></tbody></table><h3 id="post-v1-artifacts-presign" tabindex="-1"><code>POST /v1/artifacts/presign</code> <a class="header-anchor" href="#post-v1-artifacts-presign" aria-label="Permalink to &quot;`POST /v1/artifacts/presign`&quot;">​</a></h3><p>Request a presigned upload URL so a reporter can push screenshots, video and traces straight to object storage.</p><p><strong>Auth:</strong> project token with the <code>ingest</code> scope (<code>Authorization: Bearer …</code>)</p><p><strong>Returns:</strong> <code>{ url, key, headers }</code>, or <code>404</code> when artifact storage is disabled</p><p><strong>ArtifactPresignRequest</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>idempotencyKey</code></td><td>string</td><td>yes</td><td></td></tr><tr><td><code>artifacts</code></td><td>object[]</td><td>yes</td><td></td></tr></tbody></table><h3 id="get-v1-runs-summary" tabindex="-1"><code>GET /v1/runs/summary</code> <a class="header-anchor" href="#get-v1-runs-summary" aria-label="Permalink to &quot;`GET /v1/runs/summary`&quot;">​</a></h3><p>Roll-up for one commit, used by the PR comment action.</p><p><strong>Auth:</strong> project token with the <code>ingest</code> scope (<code>Authorization: Bearer …</code>)</p><p><strong>Returns:</strong> Run summary for the commit, or <code>404</code> when it has not been ingested</p><h3 id="get-v1-runs-gate" tabindex="-1"><code>GET /v1/runs/gate</code> <a class="header-anchor" href="#get-v1-runs-gate" aria-label="Permalink to &quot;`GET /v1/runs/gate`&quot;">​</a></h3><p>Quality-gate verdict for a commit: which failures are new versus already flaky on the base branch.</p><p><strong>Auth:</strong> project token with the <code>ingest</code> scope (<code>Authorization: Bearer …</code>)</p><p><strong>Returns:</strong> Gate verdict with per-test classification</p><h3 id="put-v1-codeowners" tabindex="-1"><code>PUT /v1/codeowners</code> <a class="header-anchor" href="#put-v1-codeowners" aria-label="Permalink to &quot;`PUT /v1/codeowners`&quot;">​</a></h3><p>Upload the repository CODEOWNERS file so tests can be attributed to their owners.</p><p><strong>Auth:</strong> project token with the <code>ingest</code> scope (<code>Authorization: Bearer …</code>)</p><p><strong>Returns:</strong> <code>{ ok: true }</code></p><p><strong>CodeownersUpload</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>content</code></td><td>string</td><td>yes</td><td></td></tr></tbody></table><h3 id="put-v1-notifications-routing" tabindex="-1"><code>PUT /v1/notifications/routing</code> <a class="header-anchor" href="#put-v1-notifications-routing" aria-label="Permalink to &quot;`PUT /v1/notifications/routing`&quot;">​</a></h3><p>Upload notification routing from <code>flakemetry.yml</code>, replacing the config-managed channels.</p><p><strong>Auth:</strong> project token with the <code>ingest</code> scope (<code>Authorization: Bearer …</code>)</p><p><strong>Returns:</strong> <code>{ ok: true, channels }</code></p><h3 id="post-v1-tests-testidentityid-quarantine" tabindex="-1"><code>POST /v1/tests/:testIdentityId/quarantine</code> <a class="header-anchor" href="#post-v1-tests-testidentityid-quarantine" aria-label="Permalink to &quot;`POST /v1/tests/:testIdentityId/quarantine`&quot;">​</a></h3><p>Quarantine a test, release it, or hand it back to the scorer. A <code>quarantined</code> or <code>released</code> decision is a person overriding the automation, and the scorer stops moving that test until <code>auto</code> returns it.</p><p><strong>Auth:</strong> project token with the <code>quarantine</code> scope (<code>Authorization: Bearer …</code>)</p><p><strong>Returns:</strong> <code>{ quarantined, override, changed }</code>, or <code>404</code> when the test is not in this project</p><p><strong>QuarantineSetRequest</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>decision</code></td><td><code>&quot;quarantined&quot;</code> | <code>&quot;released&quot;</code> | <code>&quot;auto&quot;</code></td><td>yes</td><td>quarantined and released are a person deciding; auto returns the test to the scorer</td></tr><tr><td><code>reason</code></td><td>string</td><td>no</td><td>Why, shown beside the test</td></tr></tbody></table><h3 id="get-openapi-json" tabindex="-1"><code>GET /openapi.json</code> <a class="header-anchor" href="#get-openapi-json" aria-label="Permalink to &quot;`GET /openapi.json`&quot;">​</a></h3><p>Machine-readable description of the read API, generated from the route table.</p><p><strong>Auth:</strong> none</p><p><strong>Returns:</strong> An OpenAPI 3.1 document</p><h3 id="get-v1-runs" tabindex="-1"><code>GET /v1/runs</code> <a class="header-anchor" href="#get-v1-runs" aria-label="Permalink to &quot;`GET /v1/runs`&quot;">​</a></h3><p>List runs newest first, cursor-paginated.</p><p><strong>Auth:</strong> project token with the <code>read</code> scope (<code>Authorization: Bearer …</code>)</p><p><strong>Returns:</strong> <code>{ items, nextCursor }</code></p><h3 id="get-v1-runs-runid" tabindex="-1"><code>GET /v1/runs/:runId</code> <a class="header-anchor" href="#get-v1-runs-runid" aria-label="Permalink to &quot;`GET /v1/runs/:runId`&quot;">​</a></h3><p>One run with its execution counts.</p><p><strong>Auth:</strong> project token with the <code>read</code> scope (<code>Authorization: Bearer …</code>)</p><p><strong>Returns:</strong> A run, or <code>404</code></p><h3 id="get-v1-tests-testidentityid" tabindex="-1"><code>GET /v1/tests/:testIdentityId</code> <a class="header-anchor" href="#get-v1-tests-testidentityid" aria-label="Permalink to &quot;`GET /v1/tests/:testIdentityId`&quot;">​</a></h3><p>One test identity with its recent execution history.</p><p><strong>Auth:</strong> project token with the <code>read</code> scope (<code>Authorization: Bearer …</code>)</p><p><strong>Returns:</strong> A test identity, or <code>404</code></p><h3 id="get-v1-flaky" tabindex="-1"><code>GET /v1/flaky</code> <a class="header-anchor" href="#get-v1-flaky" aria-label="Permalink to &quot;`GET /v1/flaky`&quot;">​</a></h3><p>The flaky board: scored tests, worst first.</p><p><strong>Auth:</strong> project token with the <code>read</code> scope (<code>Authorization: Bearer …</code>)</p><p><strong>Returns:</strong> <code>{ items }</code></p><h3 id="get-v1-executions-executionid-rca" tabindex="-1"><code>GET /v1/executions/:executionId/rca</code> <a class="header-anchor" href="#get-v1-executions-executionid-rca" aria-label="Permalink to &quot;`GET /v1/executions/:executionId/rca`&quot;">​</a></h3><p>Root-cause analysis for one execution, when there is one.</p><p><strong>Auth:</strong> project token with the <code>read</code> scope (<code>Authorization: Bearer …</code>)</p><p><strong>Returns:</strong> An RCA report, or <code>null</code></p><h3 id="get-v1-health" tabindex="-1"><code>GET /v1/health</code> <a class="header-anchor" href="#get-v1-health" aria-label="Permalink to &quot;`GET /v1/health`&quot;">​</a></h3><p>Project health metrics over a window.</p><p><strong>Auth:</strong> project token with the <code>read</code> scope (<code>Authorization: Bearer …</code>)</p><p><strong>Returns:</strong> Health metrics</p><h3 id="get-v1-export" tabindex="-1"><code>GET /v1/export</code> <a class="header-anchor" href="#get-v1-export" aria-label="Permalink to &quot;`GET /v1/export`&quot;">​</a></h3><p>Every row this project holds, streamed as a gzipped NDJSON archive: a manifest line, one line per row, an artifact inventory and a closing summary. Ingest token hashes and webhook signing secrets are left out.</p><p><strong>Auth:</strong> project token with the <code>read</code> scope (<code>Authorization: Bearer …</code>)</p><p><strong>Returns:</strong> <code>application/gzip</code>, saved as <code>flakemetry-&lt;project&gt;-&lt;date&gt;.ndjson.gz</code></p><h2 id="trpc" tabindex="-1">tRPC <a class="header-anchor" href="#trpc" aria-label="Permalink to &quot;tRPC&quot;">​</a></h2><p>The dashboard query API. Every procedure is scoped to the project the token belongs to.</p><h3 id="runs-list" tabindex="-1"><code>runs.list</code> <a class="header-anchor" href="#runs-list" aria-label="Permalink to &quot;`runs.list`&quot;">​</a></h3><p>Paginated run history, filterable by branch, status and time range.</p><p><strong>RunsListInput</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>branch</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>status</code></td><td><code>&quot;running&quot;</code> | <code>&quot;passed&quot;</code> | <code>&quot;failed&quot;</code> | <code>&quot;canceled&quot;</code></td><td>no</td><td></td></tr><tr><td><code>since</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>until</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>cursor</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td></td></tr></tbody></table><h3 id="run-get" tabindex="-1"><code>run.get</code> <a class="header-anchor" href="#run-get" aria-label="Permalink to &quot;`run.get`&quot;">​</a></h3><p>One run with its executions.</p><p><strong>RunGetInput</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>runId</code></td><td>string</td><td>yes</td><td></td></tr></tbody></table><h3 id="test-get" tabindex="-1"><code>test.get</code> <a class="header-anchor" href="#test-get" aria-label="Permalink to &quot;`test.get`&quot;">​</a></h3><p>One test identity: score, reason codes, stitch history and recent executions.</p><p><strong>TestGetInput</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>testIdentityId</code></td><td>string</td><td>yes</td><td></td></tr><tr><td><code>historyLimit</code></td><td>integer</td><td>no</td><td></td></tr></tbody></table><h3 id="flaky-board" tabindex="-1"><code>flaky.board</code> <a class="header-anchor" href="#flaky-board" aria-label="Permalink to &quot;`flaky.board`&quot;">​</a></h3><p>The flaky board — tests ranked by score, optionally scoped to an owner.</p><p><strong>FlakyBoardInput</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>limit</code></td><td>integer</td><td>no</td><td></td></tr><tr><td><code>minScore</code></td><td>number</td><td>no</td><td></td></tr><tr><td><code>includeQuarantined</code></td><td>boolean</td><td>no</td><td></td></tr><tr><td><code>owner</code></td><td>string</td><td>no</td><td></td></tr></tbody></table><h3 id="rca-get" tabindex="-1"><code>rca.get</code> <a class="header-anchor" href="#rca-get" aria-label="Permalink to &quot;`rca.get`&quot;">​</a></h3><p>The root-cause report for one execution, when one exists.</p><p><strong>RcaGetInput</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>executionId</code></td><td>string</td><td>yes</td><td></td></tr></tbody></table><h3 id="health-metrics" tabindex="-1"><code>health.metrics</code> <a class="header-anchor" href="#health-metrics" aria-label="Permalink to &quot;`health.metrics`&quot;">​</a></h3><p>Flaky MTTR, introduced-versus-resolved and quarantine backlog, optionally per team.</p><p><strong>TestHealthInput</strong></p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>days</code></td><td>integer</td><td>no</td><td></td></tr><tr><td><code>owner</code></td><td>string</td><td>no</td><td></td></tr></tbody></table>',121)])])}const g=e(a,[["render",n]]);export{l as __pageData,g as default};
